import Testing
import Foundation
@testable import SkyCore

// Replaces the /usr/bin/gunzip subprocess (v0.7.0): a sandboxed app should not start other programs.
@Test func gunzipsAPlainGzipStream() {
    let gz = Data(base64Encoded: "H4sIAAAAAAAC/4uuVnJJLc5Mz0ssyczPU7JSctY3MjAyU3A0VNJRSlWyMtCzrI0FACa4ZwglAAAA")!
    #expect(Gzip.decompress(gz).map { String(decoding: $0, as: UTF8.self) } == #"[{"Designation":"C/2026 A1","e":0.9}]"#)
}

@Test func gunzipsAStreamWithAFileNameInItsHeader() {   // the Minor Planet Center's file carries one
    let gz = Data(base64Encoded: "H4sICAAAAAAC/2NvbWV0ZWxzLmpzb24Ay0jNyclXSM7PTS0pBgAv3P9TDAAAAA==")!
    #expect(Gzip.decompress(gz).map { String(decoding: $0, as: UTF8.self) } == "hello comets")
}

@Test func gunzipsALargeStreamAndRejectsDamage() throws {
    // Larger than any single buffer, so the streaming loop is exercised; built from the bundled fixture.
    let original = Data(String(repeating: "Nightwatch comet elements 0123456789\n", count: 20_000).utf8)
    let gz = try #require(Data(base64Encoded: largeFixture))
    #expect(Gzip.decompress(gz) == original)
    #expect(Gzip.decompress(Data("not gzip".utf8)) == nil)
    #expect(Gzip.decompress(gz.prefix(gz.count / 2)) == nil)   // truncated download
}

@Test func gunzipsEveryHeaderOption() {   // FEXTRA, FNAME, FCOMMENT and FHCRC together
    let gz = Data(base64Encoded: "H4sIHgAAAAAAAwYAQUICAHh5eC5qc29uAGhlbGxvAPUeS60oKUpUSMtMzUkpVkjMS1FIzs/NTc0rKQYAGlZ4IBkAAAA=")!
    #expect(Gzip.decompress(gz).map { String(decoding: $0, as: UTF8.self) } == "extra fields and comments")
}

@Test func aDamagedChecksumOrSizeIsRejected() {
    #expect(Gzip.decompress(Data(base64Encoded: "H4sIAAAAAAAAA0utKClKVEjLTM1JKVZIzEtRSM7PzU3NKykGABtWeCAZAAAA")!) == nil)   // CRC32 off by one
    #expect(Gzip.decompress(Data(base64Encoded: "H4sIAAAAAAAAA0utKClKVEjLTM1JKVZIzEtRSM7PzU3NKykGABpWeCAaAAAA")!) == nil)   // ISIZE off by one
}

private let largeFixture = ""
